export const LUAT: Record<string, string> = {
  "ai": "# Năng lực AI (khi giáo viên chọn tích hợp năng lực AI)\n\nHướng dẫn của khung (nguyên văn):\n\n- \"Môn có dữ kiện chuẩn để đối chiếu (văn bản tác phẩm, sử liệu, bản đồ, số liệu thống kê, kết quả thí nghiệm, kết quả chạy chương trình) rất thuận lợi để HS kiểm chứng phản hồi AI.\"\n- \"Ngữ văn, Ngoại ngữ: AI chỉ dùng để gợi ý ý tưởng, chỉ ra lỗi, không viết thay bài. Lịch sử, Địa lí: đặc biệt đối chiếu mốc thời gian, tên riêng, số liệu với nguồn chính thống. Toán, KHTN: kiểm tra lại từng bước tính và đơn vị.\"\n- Câu lệnh mẫu có dạng: Hãy gợi ý các điểm cần kiểm tra khi (nêu nhiệm vụ cụ thể của bài), không viết câu trả lời hoàn chỉnh. Phần trong ngoặc đơn phải thay bằng nội dung cụ thể.\n- HS tự làm trước, dùng AI để gợi ý, sau đó kiểm chứng và diễn đạt lại; không nhập dữ liệu cá nhân.",
  "bieu_hien": "# Cách viết biểu hiện năng lực (năng lực đặc thù, năng lực số)\n\nCấu trúc biểu hiện năng lực do giáo viên quy định:\n\nHành động quan sát được + Nội dung kiến thức/kĩ năng + Kết quả cần đạt.\n\nCó thể bổ sung bối cảnh, công cụ hoặc điều kiện thực hiện khi cần thiết.\n\nVí dụ của giáo viên. Không viết kiểu để trống chỗ chờ điền như: Mô hình hóa toán học: chuyển tình huống (để trống) thành (hàm số/phương trình) và giải (HĐ III). Mà viết:\n\nHọc sinh nhận diện được các đại lượng và mối quan hệ trong tình huống thực tiễn; biểu diễn được mối quan hệ đó bằng mô hình toán học phù hợp và sử dụng mô hình để giải quyết vấn đề.\n\nLuật cho phần viết:\n- Mỗi biểu hiện là câu hoàn chỉnh, nói rõ học sinh làm gì (động từ quan sát được: nhận diện, trình bày, tiến hành, vẽ, viết, giải thích, đánh giá…), với nội dung kiến thức/kĩ năng cụ thể của bài, và đạt kết quả gì (dùng \"được\").\n- Biểu hiện năng lực đặc thù bắt đầu bằng \"Học sinh\".\n- Biểu hiện năng lực số: không viết chữ \"HS\" hay \"Học sinh\" ở đầu (app tự thêm), bắt đầu bằng động từ thao tác số; nêu công cụ số khi cần.\n- Gắn với nội dung cụ thể của bài, không viết chung chung cho mọi bài; không ghi tên hoạt động trong câu (vị trí ghi riêng).\n- Mỗi năng lực ghi vào mục tiêu phải đi đủ chuỗi: mục tiêu năng lực → hoạt động học → hành vi HS → sản phẩm → tiêu chí đánh giá. Thiếu mắt xích nào thì không chọn năng lực đó.\n- Không chép tên hay định nghĩa năng lực làm biểu hiện; không liệt kê chung chung.\n- Năng lực đặc thù: chọn 1–3 thành phần của đúng môn, mỗi thành phần gắn với yêu cầu cần đạt của bài; không tự đặt mã, không dùng mã của khung năng lực khác.\n- Không thay đổi nội dung kiến thức của bài chỉ để gắn một năng lực. Biểu hiện không lặp giữa các nhóm năng lực.",
  "cau_hoi": "# Câu hỏi\n\nHướng dẫn của khung (nguyên văn):\n\n- Câu hỏi tự học: \"Mỗi mức 1–2 câu, bám SGK để hệ thống chấm được; mỗi phương án sai ứng với một lỗi hiểu thường gặp.\"\n- Câu hỏi luyện tập: \"Mỗi phương án sai nên ứng với một lỗi hiểu thường gặp; câu đúng sai nên đặt trong tình huống, bảng dữ liệu, tư liệu hoặc mô tả cụ thể. Ghi mức độ cho từng câu.\"\n- \"Các môn thi tốt nghiệp THPT tham khảo cấu trúc định dạng đề thi từ năm 2025; GV đối chiếu lại với văn bản hiện hành của Bộ GD&ĐT.\"\n\nLuật cho phần viết:\n- Số câu, dạng câu và mức độ do app tính sẵn; viết đúng số lượng được yêu cầu.\n- Trắc nghiệm nhiều lựa chọn có đúng 4 phương án, đúng 1 đáp án; ghi lỗi hiểu ứng với từng phương án sai và lời giải.\n- Có câu tương tự cho lượt 2 khi được yêu cầu.\n- Câu exit ticket không trùng câu luyện tập.",
  "cong_thuc": "# Công thức\n\n- Mọi công thức toán, lí, hóa viết bằng LaTeX đặt trong $...$, ví dụ $x^{2}-5x+6\\le 0$, $\\frac{1}{2}$.\n- Phương trình hóa học dùng \\ce{...} trong $...$, ví dụ $\\ce{CH3COOC2H5 + NaOH -> CH3COONa + C2H5OH}$.\n- Không dùng kí tự ², ³, √, ∑ ngoài $...$. Không dùng $$...$$.",
  "doc_hinh": "# Đọc hình trong giáo án\n\nNhiệm vụ: đọc đúng nội dung một hình trong giáo án của giáo viên để app vẽ lại. Chỉ ghi điều nhìn thấy trên hình\nhoặc ghi rõ trong đoạn văn quanh hình. Không suy đoán, không tự tính thêm, không sửa chỗ có vẻ sai.\n\n- `loai`: bang_bien_thien (bảng biến thiên), do_thi (đồ thị hàm số trên hệ trục), cong_thuc (công thức, phương trình\n  được chụp thành ảnh), bang (bảng số liệu, bảng chữ), khac (hình minh họa, sơ đồ, ảnh chụp, hình hình học…).\n- `ham`: công thức hàm số viết trên hình hoặc trong đoạn văn quanh hình (vd \"y = x^3 - 3x + 1\", \"\\frac{2x+1}{x-1}\").\n  Không có thì để trống; không đoán hàm số từ hình dạng đồ thị hay bảng.\n- Bảng biến thiên: `x` là nhãn các mốc theo thứ tự trái sang phải, gồm cả $-\\infty$, $+\\infty$ (viết \"-\\infty\", \"+\\infty\").\n  `daoHamMoc`: chữ ghi ở hàng y' ngay tại mỗi mốc (\"0\", \"||\" hoặc \"\"). `daoHam`: dấu y' trên từng khoảng (\"+\" hoặc \"-\"),\n  số phần tử ít hơn số mốc một. `y`: giá trị ghi ở hàng y tại mỗi mốc; tại tiệm cận đứng ghi \"giá trị trái||giá trị phải\".\n  Nhãn viết như trên hình, dùng LaTeX cho phân số, căn (\"\\frac{1}{2}\", \"1-\\sqrt{2}\").\n- Đồ thị: `diem` là các điểm có tọa độ ghi rõ trên hình (chấm, nét đứt chiếu xuống trục, nhãn số); không ước lượng\n  điểm không ghi số. `tiemCanDung`, `tiemCanNgang`: đường tiệm cận vẽ nét đứt có ghi số.\n- Công thức: `congThuc` viết bằng LaTeX, không có dấu $; phương trình hóa học dùng \\ce{...}.\n- Bảng: `bang` là các hàng, mỗi hàng các ô chữ; công thức trong ô viết $...$. Ô gộp thì ghi nội dung vào ô đầu, ô sau để trống.\n- Trường không dùng đến để trống (chuỗi rỗng, mảng rỗng).\n- `chacChan`: cao khi đọc rõ mọi chữ, số; vua khi có chỗ mờ phải đoán; thap khi hình mờ, bị cắt hoặc không chắc loại hình.\n- `moTa`: một câu tiếng Việt nói hình thể hiện gì (vd \"Bảng biến thiên của hàm số $y=x^3-3x+1$ trên $\\mathbb{R}$\").",
  "hoat_dong": "# Thiết kế hoạt động dạy học (HĐ I – IV, nhiệm vụ tích hợp)\n\nYêu cầu của giáo viên:\n\n- \"Không áp dụng máy móc; không phải hoạt động nào cũng cần trò chơi hoặc công nghệ.\"\n- \"Nếu tích hợp năng lực số, hoạt động phải có hành vi số thực tế. Đóng kịch đơn thuần không đủ làm minh chứng năng lực số.\"\n- \"Ưu tiên cải tiến hoạt động hiện có thay vì thêm hoạt động mới.\"\n- \"Không làm thay đổi thời lượng toàn tiết. Nếu bổ sung một nhiệm vụ, cần điều chỉnh các bước trong chính hoạt động đó để đủ thời gian.\"\n- \"Không tạo hoạt động quá dài, quá nhiều thao tác hoặc cần thiết bị không có trong đầu vào.\"\n\nVí dụ của giáo viên (Khởi động – Tin học 10): thay vì chỉ ghi \"GV đặt câu hỏi, HS trả lời\", có thể đề xuất đóng vai tình huống một nhóm học sinh cần lưu trữ 600 ảnh kỉ yếu vào USB 2 GB. Ba học sinh đóng vai nhóm trưởng, người phụ trách ảnh và người tư vấn công nghệ. Các nhân vật có quan điểm khác nhau, tạo tình huống để cả lớp tính toán và đưa ra phương án.\n\nLuật cho phần viết:\n- Trước khi viết, cân nhắc: mục tiêu kiến thức và năng lực của hoạt động, nội dung bài, độ tuổi học sinh, thời lượng, thiết bị và học liệu có sẵn; từ đó chọn cách tổ chức phù hợp (đóng vai, đóng kịch tình huống; trò chơi học tập; thảo luận cặp đôi/nhóm; giải quyết tình huống thực tiễn; trạm học tập; khăn trải bàn, mảnh ghép; thí nghiệm, thực hành; dự án nhỏ; sử dụng công cụ số; hoặc phương pháp khác hợp môn).\n- Không viết câu chung chung như \"GV giao nhiệm vụ, HS thảo luận, đại diện trình bày, GV nhận xét\". Mỗi bước nêu cụ thể: GV đưa dữ liệu, câu hỏi, vai, tiêu chí gì; HS làm thao tác gì, tạo ra sản phẩm gì.\n- Mỗi hoạt động thể hiện rõ: mục tiêu; nội dung và nhiệm vụ; cách tổ chức; hành động của GV và HS; thời gian từng bước (tổng bằng đúng thời lượng hoạt động); sản phẩm học tập; cách kiểm tra, đánh giá.\n- Tối đa 3 bước cho hoạt động dưới 10 phút, tối đa 5 bước cho hoạt động dài hơn.\n- Chỉ dùng thiết bị, học liệu trong danh sách có sẵn và đồ dùng lớp học thông thường (bảng, giấy, bút, SGK, phiếu học tập). Không có máy tính, điện thoại, máy chiếu trong danh sách thì không dùng.\n- Dùng lại tình huống, tư liệu, câu hỏi của giáo viên (ghi mã đoạn); không đổi nội dung kiến thức của bài.",
  "khong_ai": "# Khi giáo viên KHÔNG chọn tích hợp năng lực AI\n\n- Không nhắc AI, trí tuệ nhân tạo, chatbot, câu lệnh (prompt), phiếu kiểm chứng phản hồi AI.\n- Được nhắc chatbot của nền tảng tự học như một học liệu, nếu giáo viên đã khai báo nền tảng đó.",
  "lhdn": "",
  "luat_loi": "# Luật viết chung (luôn áp dụng)\n\n- Viết tiếng Việt chuẩn mực văn bản chuyên môn, câu ngắn, cụ thể.\n- Không dùng lời sáo rỗng: \"góp phần nâng cao\", \"một cách hiệu quả\", \"đa dạng phong phú\", \"trong thời đại 4.0\".\n- Không lặp ý giữa các mục.\n- Không ghi số liệu giả định của lớp. Khung ghi: \"Không ghi sẵn số liệu giả định (\"Câu 1 sai nhiều nhất\", \"42% HS chọn B\") vì KHBD soạn trước khi có dữ liệu.\"\n- Chỉ nhắc nền tảng số và hình thức tổ chức mà giáo viên đã chọn. Phần giáo viên không chọn thì không viết.\n- Mọi danh sách là mảng JSON, mỗi phần tử một ý, không có kí hiệu đầu dòng (\"-\", \"+\", \"•\") ở đầu phần tử.\n- Không chép lại văn bản của giáo viên. Khi cần dùng nội dung của giáo viên, chỉ ghi mã đoạn vào trường dành cho mã (vd trường mã đoạn tình huống); không viết mã đoạn (MT-01, HD-03…) vào câu văn.\n- Chỉ viết nội dung dùng trên lớp. Không viết lời nhắn cho người soạn, điều kiện hay ghi chú kiểu \"nếu giáo án cũ không có…\", \"nếu GV chưa ghi…\", không nhắc tên trường dữ liệu.\n- Không ghi lại mã năng lực ở đầu biểu hiện, tiêu chí, mô tả (app tự ghi mã trước nội dung).\n- Mỗi nhiệm vụ nêu một lần trong một hoạt động. Việc đã có ở một bước thì không viết lại ở câu khác; câu hỏi, tình huống, nhận định là chi tiết của bước, không nhắc lại \"GV đưa ra…\".\n- Không chép lại câu ở mục tiêu vào hoạt động; hoạt động nêu việc làm, sản phẩm, tiêu chí.\n- Chỉ nhắc mục có thật trong bài (vd \"Vận dụng 1\" khi có Vận dụng 1); không nhắc phụ lục, phiếu không có.\n- Câu đủ chủ ngữ (GV, HS, nhóm…), dấu câu đúng; không để \".;\", \"..\", \".?\", \":;\", hai từ giống nhau liền nhau.\n- Mục tiêu năng lực của KHBD gốc chỉ là tư liệu tham khảo: chọn năng lực theo dữ liệu và yêu cầu cần đạt của bài, không chép lại hay ghép thêm dòng năng lực của bản gốc.\n- Mỗi phần tử danh sách là một ý ngắn: câu hỏi và đáp án ở hai trường riêng, mỗi phương án một phần tử, mỗi bước một phần tử; không gộp nhiều bước hay nhiều ý vào một đoạn dài.\n- Không bao giờ để lại chỗ trống chờ điền (ngoặc vuông hoặc dãy dấu chấm).\n- Bám yêu cầu cần đạt của bài; không thêm kiến thức ngoài chương trình.\n\n## Hướng dẫn của khung về các hoạt động (nguyên văn)\n\n- HĐ I: \"Soạn sẵn 2–3 nhận định ứng với lỗi hay gặp; GV chọn theo kết quả tự học thật của HS. Không giảng lại toàn bộ lí thuyết.\"\n- HĐ II: \"Dù chọn hình thức nào, HĐ II luôn giữ 3 yếu tố: có phân hóa theo nhóm mức đạt; HS nhận phản hồi và sửa lỗi ngay trong hoạt động; có sản phẩm hoặc kết quả ghi lại được để đánh giá.\"\n- HĐ II, hình thức không dùng câu hỏi: \"Hình thức khác (phiên tòa, đóng vai, tranh biện...) thì thay bằng: tư liệu/tình huống, phân vai, câu hỏi định hướng và tiêu chí đánh giá; có thể giữ 3–5 câu để kiểm tra nhanh cuối hoạt động.\"\n- Tình huống mở đầu ở HĐ I được giải trọn vẹn ở HĐ III.\n- Bài có thí nghiệm, thực hành kĩ thuật hoặc vận động phải ghi kèm biện pháp bảo đảm an toàn.",
  "nls": "# Năng lực số (khi giáo viên chọn tích hợp năng lực số)\n\nHướng dẫn của khung (nguyên văn):\n\n\"Mô tả mã lấy đúng nguyên văn theo khung năng lực số hiện hành (Thông tư 02/2025/TT-BGDĐT). Vị trí của mỗi mã do nội dung bài quyết định: mã có thể nằm ở bất kì giai đoạn, hoạt động hay tiết nào có nhiệm vụ số tương ứng; nhiều mã có thể cùng một hoạt động; không bắt buộc đủ 3 mã. Mỗi mã có đủ: mô tả – biểu hiện – vị trí – minh chứng – tiêu chí; cùng một vị trí phải ghi khớp ở mục I.2, trong hoạt động tương ứng và trong ma trận mục V. Không thêm mã chỉ vì có dùng nền tảng số (LMS, Quizizz...).\"\n\nLuật cho phần viết:\n- Chọn mã căn cứ vào nội dung kiến thức của bài (yêu cầu cần đạt, loại kiến thức: số liệu, tư liệu, mô hình, thí nghiệm, sản phẩm…) và cách tổ chức hoạt động (hình thức HĐ II, HĐ III, kĩ thuật dạy học, tự học trước giờ). Nhiệm vụ số phải giúp HS đạt yêu cầu cần đạt của bài, không thêm vào cho có.\n- Khi gợi ý mã, lí do nêu rõ căn cứ nội dung và căn cứ tổ chức.\n- Chỉ giữ mã có nhiệm vụ số thực tế trong một hoạt động của bài; mã giáo viên chọn mà bài không có hoạt động tương ứng thì đưa vào boQua kèm lí do, không gắn gượng ép.\n- Nhiệm vụ số phải là thao tác số thật trên công cụ số có sẵn (thiết bị trong giáo án hoặc nền tảng giáo viên chọn); đóng kịch, thảo luận đơn thuần không đủ làm minh chứng. Lớp không có thiết bị thì giao làm ở nhà và ghi rõ, hoặc đưa mã vào boQua.\n- Ghi số phút của nhiệm vụ số và lấy thời gian từ bước nào trong chính hoạt động đó; không làm tăng thời lượng tiết học.\n- Ưu tiên tích hợp vào hoạt động có sẵn của giáo viên; không tạo hoạt động mới. Mỗi mã chỉ gắn một hoạt động, một lần.\n- Nêu rõ hành vi HS (biểu hiện), công cụ số dùng (loại công cụ hoặc tên giáo viên đã chọn), sản phẩm/minh chứng và tiêu chí đánh giá.\n- Chỉ chọn mã trong danh sách được cung cấp; không tự đặt mã. Không viết lại mô tả của mã: app tự chép nguyên văn.\n- Biểu hiện: hành vi số cụ thể của HS, bắt đầu bằng động từ thao tác (tìm kiếm, đối chiếu, tạo, lưu, chia sẻ…).\n- Vị trí: chọn trong danh sách vị trí của bài.\n- Minh chứng: sản phẩm số HS tạo và lưu.\n- Tiêu chí: \"đạt khi …\", kiểm tra được.",
  "tieng_anh": "# Phụ lục tiếng Anh (khi giáo viên chọn tích hợp tiếng Anh)\n\nHướng dẫn của khung (nguyên văn):\n\n- \"GV chọn 01 hoạt động bất kì trong HĐ I – IV (nên chọn hoạt động thể hiện rõ nhất đặc trưng của bài, thường là HĐ III) và dịch toàn bộ hoạt động đó sang tiếng Anh: tên hoạt động, thời lượng, mục tiêu, tổ chức, câu hỏi/nhiệm vụ, sản phẩm – đánh giá. Giữ nguyên mã năng lực (1.1.NC1a, 6.3.NC1b...), tên riêng và tên nền tảng. Dùng bảng thuật ngữ dưới đây để dịch thống nhất.\"\n- \"Dịch sát nội dung tiếng Việt của hoạt động đã chọn, không thêm hoặc bớt ý; câu ngắn, rõ, ưu tiên thì hiện tại đơn và chủ ngữ \"Students/The teacher\".\"\n- Các kí hiệu dạng ⟦1⟧, ⟦2⟧ là mã năng lực hoặc tên nền tảng: giữ nguyên, không dịch.\n- Bản dịch không được còn chữ tiếng Việt có dấu.\n\n## CLIL trong hoạt động (khi giáo viên chọn CLIL)\n\nHướng dẫn của khung (nguyên văn):\n\n- \"GV sử dụng tiếng Việt là chính, chỉ xen kẽ các key words/cụm thuật ngữ tiếng Anh cần thiết của từng hoạt động; HS nhận biết, đọc và dùng các key words đó khi thao tác, ghi phiếu hoặc báo cáo ngắn; không yêu cầu nói câu tiếng Anh hoàn chỉnh.\"\n\nLuật cho phần viết:\n- Chỉ tích hợp vào đúng một hoạt động được chỉ định; không dịch, không sửa mục tiêu và các hoạt động khác.\n- Key words đúng thuật ngữ của môn, vừa sức cấp lớp; mỗi từ kèm nghĩa tiếng Việt.\n- Nhiệm vụ nêu rõ HS dùng key words vào việc gì trong hoạt động (ghi phiếu, gắn nhãn sơ đồ, báo cáo ngắn).",
  "to_chuc": "# Cách tổ chức HĐ II, HĐ III (gợi ý theo nội dung bài và soạn hoạt động)\n\nHướng dẫn của khung (nguyên văn):\n\n- HĐ II: \"Dù chọn hình thức nào, HĐ II luôn giữ 3 yếu tố: có phân hóa theo nhóm mức đạt; HS nhận phản hồi và sửa lỗi ngay trong hoạt động; có sản phẩm hoặc kết quả ghi lại được để đánh giá. Thời lượng từng bước do GV chia, tổng bằng thời lượng HĐ II.\"\n- HĐ II: \"Hình thức khác (phiên tòa, đóng vai, tranh biện...) thì thay bằng: tư liệu/tình huống, phân vai, câu hỏi định hướng và tiêu chí đánh giá; có thể giữ 3–5 câu để kiểm tra nhanh cuối hoạt động.\"\n- HĐ III: \"Chỉ 1 nhiệm vụ, thường là giải tình huống mở đầu; nhóm 3–4 HS\"\n- HĐ III: \"Môn có thí nghiệm, thực hành kĩ thuật, vận động: HĐ III ưu tiên thí nghiệm/thao tác ngắn hoặc thí nghiệm biểu diễn của GV, HS quan sát và giải thích.\"\n\nLuật cho phần viết:\n- Chọn hình thức căn cứ vào nội dung kiến thức của bài (yêu cầu cần đạt, loại kiến thức) và bảng gợi ý hình thức HĐ II, gợi ý nhiệm vụ HĐ III theo môn của khung được cung cấp; ưu tiên hình thức có trong bảng.\n- Lí do nêu rõ căn cứ: nội dung nào của bài, dòng nào của bảng khung.\n- Diễn biến và nhiệm vụ viết cụ thể với nội dung bài (tên kiến thức, tư liệu, số liệu, tình huống của bài), không chép lại câu chung chung của bảng.\n- Dùng lại tình huống, tư liệu, nhiệm vụ đã có trong giáo án của giáo viên khi phù hợp.\n- Không đưa tên nền tảng số nào nếu giáo viên chưa chọn."
};
